    public Object parseTrade(Object trade, Map<String, Object> market)
    {
        //
        // fetchTrades
        //
        //       {             market: "BTC-ETH",
        //             "trade_date_utc": "2018-11-22",
        //             "trade_time_utc": "13:55:24",
        //                  "timestamp":  1542894924397,
        //                "trade_price":  0.02914289,
        //               "trade_volume":  0.20074397,
        //         "prev_closing_price":  0.02966,
        //               "change_price":  -0.00051711,
        //                    "ask_bid": "ASK",
        //              "sequential_id":  15428949259430000 }
        //
        // fetchOrder trades
        //
        //         {
        //             "market": "KRW-BTC",
        //             "uuid": "78162304-1a4d-4524-b9e6-c9a9e14d76c3",
        //             "price": "101000.0",
        //             "volume": "0.77368323",
        //             "funds": "78142.00623",
        //             "ask_fee": "117.213009345",
        //             "bid_fee": "117.213009345",
        //             "created_at": "2018-04-05T14:09:15+09:00",
        //             "side": "bid",
        //         }
        //
        String id = this.safeString2(trade, "sequential_id", "uuid");
        Object orderId = null;
        Long timestamp = this.safeInteger(trade, "timestamp");
        if (java.util.Objects.equals(timestamp, null))
        {
            timestamp = this.parse8601(this.safeString(trade, "created_at"));
        }
        String side = null;
        String askOrBid = this.safeStringLower2(trade, "ask_bid", "side");
        if (java.util.Objects.equals(askOrBid, "ask"))
        {
            side = "sell";
        } else if (java.util.Objects.equals(askOrBid, "bid"))
        {
            side = "buy";
        }
        String cost = this.safeString(trade, "funds");
        String price = this.safeString2(trade, "trade_price", "price");
        String amount = this.safeString2(trade, "trade_volume", "volume");
        String marketId = this.safeString2(trade, "market", "code");
        market = (Map<String, Object>) (this.safeMarket(marketId, market, "-"));
        Map<String, Object> fee = null;
        String feeCost = this.safeString(trade, (askOrBid + "_fee"));
        if (!java.util.Objects.equals(feeCost, null))
        {
            final Map<String, Object> finalMarket = market;
            final String finalFeeCost = feeCost;
            fee = new HashMap<String, Object>() {{
                put( "currency", ((Map<String, Object>)finalMarket).get("quote") );
                put( "cost", finalFeeCost );
            }};
        }
        final Long finalTimestamp = timestamp;
        final Map<String, Object> finalMarket_2 = market;
        final String finalSide = side;
        final Map<String, Object> finalFee = fee;
        return this.safeTrade((Map<String, Object>) (new HashMap<String, Object>() {{
            put( "id", id );
            put( "info", trade );
            put( "order", orderId );
            put( "timestamp", finalTimestamp );
            put( "datetime", Upbit.this.iso8601(finalTimestamp) );
            put( "symbol", ((Map<String, Object>)finalMarket_2).get("symbol") );
            put( "type", null );
            put( "side", finalSide );
            put( "takerOrMaker", null );
            put( "price", price );
            put( "amount", amount );
            put( "cost", cost );
            put( "fee", finalFee );
        }}), market);
    }
    public Object parseTrade(Object trade, Object... optionalArgs)
    {
        return this.parseTrade(trade, Helpers.getArgMap(optionalArgs, 0, null));
    }

